import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 63 · Christmas recipe: English toffee (Google Trends 3/11: christmas treat recipes, christmas candy rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, there's one Christmas candy that disappears from my house faster than any other. English toffee. Crisp, buttery, golden candy that snaps when you bite it, covered in chocolate and chopped almonds. I make a big pan every December, and by the time I've broken it into pieces, my son has eaten a third of it standing at the counter.""",
   "English toffee chocolate almonds pieces", "IT SNAPS")
sc("""But toffee scares people, honey. They tell me theirs separated into a greasy puddle, or turned grainy, or burned, or stuck to their teeth like glue. So tonight I'm giving you my Christmas toffee, every step, and the five mistakes that ruin it. And stay with me, because the last one is about the moment you take it off the stove, and it's all about color.""",
   "separated greasy toffee pan", "IT SEPARATED")

ch("A candy from England")
sc("""Toffee came from England, where it's been made for two hundred years with nothing but butter and sugar, cooked until it turns golden and snaps. In America, people started covering it in chocolate and nuts, and calling it English toffee, even though the English think that's a little much. The English don't know what they're missing, honey.""",
   "old English candy shop", "A LITTLE MUCH")
sc("""I learned it from Mrs. Carrington, the wife of the Methodist minister in Mansfield, who was born in Manchester, England. Every Christmas she gave every family in the church a little tin of her toffee. In nineteen sixty, when I was sixteen, I asked her for the recipe. She said, Ruth, it's only butter and sugar, but you have to watch it like a hawk.""",
   "minister's wife tins Christmas 1960", "WATCH IT LIKE A HAWK")
sc("""And here's the good news, sweetheart. Toffee only has five ingredients and takes about twenty minutes. No baking at all. You just need a heavy pot, a candy thermometer, and patience. In a minute I'll tell you the first mistake, and it's the pot.""",
   "heavy saucepan candy thermometer", "ONLY FIVE INGREDIENTS")

sc("""My first toffee, in nineteen sixty-four, was a disaster. I turned the heat all the way up because my husband was coming home for supper, and in five minutes I had a pan of black smoke and a greasy brown rock. The smoke alarm hadn't been invented yet, so the neighbor came running over with a fire extinguisher. I made meatloaf instead. My husband never knew.""",
   "smoking burnt pot kitchen 1960s", "A GREASY BROWN ROCK")

ch("What you need")
sc("""Here's what you need, honey. One cup of butter, two sticks, salted is fine. One cup of white sugar. Three tablespoons of water. A teaspoon of vanilla. And for the top, one cup of chocolate chips, or a good chocolate bar, chopped, and three quarters of a cup of almonds or pecans, toasted and chopped fine. That's it.""",
   "butter sugar chocolate almonds", "THE INGREDIENTS")
sc("""And mistake number one. A thin pot. A thin saucepan heats unevenly, and the sugar burns on the bottom in one spot while the rest isn't ready. Use a heavy saucepan, at least two quarts, with a thick bottom. And a light-colored one if you have it, so you can see the color of the toffee as it cooks.""",
   "heavy light colored saucepan", "A HEAVY POT")
sc("""Get everything ready before you start, sweetheart. Line a baking sheet with parchment or a silicone mat. Sprinkle half the chopped nuts on it. Have the chocolate chopped, the vanilla measured. Because when the toffee is ready, it's ready right then, and you don't have one second to go looking for anything.""",
   "baking sheet parchment nuts ready", "GET EVERYTHING READY")

ch("Cooking")
sc("""Step one. Put the butter, sugar, and water in the pot over medium heat. Stir it gently with a wooden spoon until the butter melts and the sugar dissolves completely. Then clip on your candy thermometer. Mistake number two is turning the heat up too high to rush it. That's the most common reason toffee separates. Keep it at medium, honey.""",
   "melting butter sugar pot", "KEEP IT AT MEDIUM")
sc("""When butter and sugar get too hot too fast, the butter fat breaks away from the sugar, and you get a greasy layer of melted butter floating on top of a hard sugar lump. That's separating. Steady, medium heat keeps them together, like a good marriage. Mrs. Carrington said, toffee is like a husband. Rush it, and it falls apart.""",
   "butter separating from sugar", "LIKE A GOOD MARRIAGE")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now stir it slowly and steadily the whole time, gently, scraping the bottom. Don't beat it or whisk it fast. Just a slow, steady stir. It'll bubble, foam up, then turn thick and creamy and pale. Then slowly it starts to turn golden.""",
   "stirring bubbling toffee pot", "A SLOW, STEADY STIR")

ch("Grainy toffee")
sc("""Mistake number three is grainy toffee. That happens when sugar crystals form on the sides of the pot and fall back in. If you see sugar crystals sticking to the sides above the toffee, brush them down with a wet pastry brush. And don't scrape the sides of the pot at the very end, when you pour it out. Leave that last bit in the pot.""",
   "pastry brush sugar crystals pot", "BRUSH DOWN THE SIDES")
sc("""And here's a trick if you live where it's humid, or if your toffee keeps separating. Add one tablespoon of light corn syrup with the sugar. It helps stop the crystals and keeps the butter and sugar together. Mrs. Carrington never used it, but she lived in a dry old house with a coal furnace. My kitchen is more like a greenhouse.""",
   "corn syrup spoon pot", "A SPOON OF CORN SYRUP")

ch("The color")
sc("""So far, a heavy pot, medium heat, a slow steady stir, and brush down the sides. Now the moment I promised, the most important one. When to take it off the stove. Mistake number four is taking it off too early. Pale toffee is soft and sticky, and it pulls out your fillings. Mistake number five is taking it off too late. Dark brown toffee tastes burnt and bitter.""",
   "golden amber toffee pot", "THE RIGHT MOMENT")
sc("""The thermometer should read three hundred to three hundred five degrees. That's the hard crack stage. And the color should be like a new copper penny, or a brown paper grocery bag. Deep golden amber. It smells like warm caramel and butter. It happens fast at the end, sweetheart. It can go from golden to burnt in thirty seconds. So don't walk away, not even for the phone.""",
   "candy thermometer 300 degrees copper", "A NEW COPPER PENNY")
sc("""The minute it's the color of a copper penny, take it off the heat, and stir in the vanilla. It'll bubble and sputter. Stand back. Then pour it right away over the nuts on the baking sheet, and spread it quickly with a spatula, about a quarter inch thick. It sets almost immediately, so you have only a few seconds.""",
   "pouring toffee onto baking sheet", "POUR IT RIGHT AWAY")

sc("""And test your thermometer first, honey, in boiling water. It should read two hundred twelve. If it's off by a few degrees, adjust for it. And if you don't have a thermometer, use the old test. Drop a little toffee into a glass of ice water. If it turns hard and brittle and snaps when you bend it, it's ready. If it bends like taffy, keep cooking.""",
   "candy dropped in ice water test", "THE ICE WATER TEST")

ch("The chocolate")
sc("""Now, right away, while the toffee is still hot, sprinkle the chopped chocolate all over the top. Wait two or three minutes, and the heat from the toffee melts it. Then spread the melted chocolate smooth with a spatula, all the way to the edges. No melting pot needed. The toffee does the work for you.""",
   "spreading melted chocolate on toffee", "THE TOFFEE DOES THE WORK")
sc("""Then sprinkle the rest of the chopped nuts over the warm chocolate, and press them in lightly with your hand. Let it cool at room temperature for about an hour, then put it in the icebox for thirty minutes, until the chocolate is completely firm. Then break it into pieces with your hands, or tap it with the handle of a knife. It snaps like glass.""",
   "breaking toffee into pieces", "IT SNAPS LIKE GLASS")

ch("Saving it")
sc("""And if it does separate, honey, don't throw it out. Take it off the heat, add two tablespoons of very hot water, and stir it hard and fast until it comes back together. Then put it back on the heat, lower this time, and keep cooking. It works most of the time. Mrs. Carrington taught me that, and it's saved my Christmas candy at least four times.""",
   "stirring toffee hot water rescue", "IT CAN BE SAVED")

sc("""And cleaning the pot, sweetheart. Don't scrub it. Hardened toffee in a pot is like cement. Just fill the pot with water, put it back on the stove, and bring it to a boil. In five minutes, all the hard candy melts right off. Pour it out, and the pot wipes clean. My husband scrubbed one of my pots for an hour once before I told him. He never forgave me.""",
   "pot filled with water boiling clean", "DON'T SCRUB IT")

ch("Keeping and giving")
sc("""Toffee keeps two weeks in an airtight tin, with wax paper between the layers, in a cool, dry place. Humid air makes it sticky, so keep the lid on tight. And it freezes for two months. It's the best candy for mailing, because it doesn't melt or crush. I send a tin to my son in Arizona every December, and he says it arrives perfect.""",
   "toffee tin wax paper layers", "THE BEST FOR MAILING")
sc("""And you can change it, sweetheart. Use pecans instead of almonds. Use dark chocolate or white chocolate. Sprinkle a little flaky sea salt on top of the chocolate, which my grandchildren love. Or crushed peppermint candies for Christmas. My grandson makes it with a little espresso powder in the chocolate, and he calls it his breakfast candy.""",
   "toffee sea salt dark chocolate", "BREAKFAST CANDY")

ch("Grandma's kitchen")
sc("""So one more time. A heavy pot. Butter, sugar and water, over medium heat, never high. A slow, steady stir. Brush down the sugar crystals. Watch it like a hawk until it's the color of a copper penny, three hundred degrees. Pour it fast over the nuts. Chocolate on top, melted by the heat. That's Mrs. Carrington's English toffee, and it never separates.""",
   "toffee pieces Christmas plate", "IT NEVER SEPARATES")
sc("""Tell me in the comments, sweetheart. Almonds or pecans in your toffee? And who in your family eats it standing at the counter? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas kitchen counter candy evening", "ALMONDS OR PECANS?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma63", "Christmas Toffee EVERYONE's Grandma Made (Why Yours SEPARATES)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Toffee, a British butter and sugar candy cooked to the hard crack stage; chocolate and nut covered English toffee in America.",
      "Recipe as written by Grandma Ruth: 1 cup butter, 1 cup sugar, 3 tbsp water, 1 tsp vanilla, cooked to 300 to 305 F; topped with 1 cup chocolate and 3/4 cup toasted chopped almonds or pecans."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
